        def generate_clean_image(filepath, product_title, brand_name, cat_slug, selling_p, mrp_p, is_gallery=False, view_num=1):
            bg_dark, accent_color = palette_map.get(cat_slug, ((30, 41, 59), (59, 130, 246)))
            width, height = (800, 800)
            img = Image.new('RGB', (width, height), color=(248, 250, 252))
            draw = ImageDraw.Draw(img)

            # Outer subtle container border
            draw.rounded_rectangle([25, 25, 775, 775], radius=24, fill=(255, 255, 255), outline=(226, 232, 240), width=3)

            # Top Brand Bar
            draw.rounded_rectangle([50, 50, 750, 125], radius=14, fill=bg_dark)
            draw.text((75, 75), f"{brand_name.upper()} • OFFICIAL INDIA STORE", fill=(255, 255, 255))
            draw.text((630, 75), "100% GENUINE", fill=(251, 191, 36))

            # Central Display Studio Box
            draw.rounded_rectangle([50, 145, 750, 600], radius=18, fill=(241, 245, 249), outline=(203, 213, 225), width=2)

            # Circular Glow
            draw.ellipse([200, 200, 600, 540], fill=(224, 231, 255))
            draw.ellipse([260, 250, 540, 490], fill=(255, 255, 255), outline=accent_color, width=4)

            # Center Icon / Badge Text
            draw.text((310, 335), brand_name[:14].upper(), fill=bg_dark)
            draw.text((295, 375), "PREMIUM QUALITY", fill=accent_color)
            if is_gallery:
                draw.text((320, 415), f"[ PERSPECTIVE {view_num} ]", fill=(100, 116, 139))
            else:
                draw.text((320, 415), "[ STUDIO SHOT ]", fill=(100, 116, 139))

            # Product Title Box
            clean_title = product_title[:42] + ("..." if len(product_title) > 42 else "")
            draw.text((70, 545), clean_title, fill=(15, 23, 42))

            # Bottom Price & Warranty Strip
            draw.rounded_rectangle([50, 620, 750, 745], radius=14, fill=(248, 250, 252), outline=(226, 232, 240), width=2)
            draw.text((75, 645), f"PRICE: Rs. {selling_p:,}", fill=(16, 185, 129))
            if mrp_p > selling_p:
                draw.text((75, 685), f"M.R.P: Rs. {mrp_p:,} (Save Rs. {mrp_p - selling_p:,})", fill=(148, 163, 184))
            draw.text((540, 665), "Shopora Assured", fill=(59, 130, 246))

            img.save(filepath, 'JPEG', quality=90)
            return filepath

        def download_or_generate_image(target_path, img_url, p_name, brand_name, cat_slug, price, mrp):
            if os.path.exists(target_path) and os.path.getsize(target_path) > 8000:
                return True

            downloaded = False
            if img_url and img_url.startswith('http'):
                try:
                    req = urllib.request.Request(
                        img_url,
                        headers={'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36'}
                    )
                    with urllib.request.urlopen(req, timeout=3.5) as resp:
                        if resp.status == 200:
                            data = resp.read()
                            if len(data) > 5000:
                                with open(target_path, 'wb') as f:
                                    f.write(data)
                                downloaded = True
                except Exception:
                    downloaded = False

            if not downloaded:
                generate_clean_image(target_path, p_name, brand_name, cat_slug, price, mrp, is_gallery=False)
            return True
