        self.stdout.write("Downloading / generating product photographs...")
        
        # Concurrently process images
        def process_img_task(p_info):
            img_rel_path = f"products/{p_info['slug']}.jpg"
            target_path = os.path.join(settings.MEDIA_ROOT, img_rel_path)
            download_or_generate_image(
                target_path,
                p_info.get('img_url'),
                p_info['name'],
                p_info['brand'],
                p_info['category'],
                p_info['price'],
                p_info['mrp']
            )
            # Perspective gallery images
            for g_idx in (1, 2):
                g_rel = f"products/gallery/{p_info['slug']}_view{g_idx}.jpg"
                g_target = os.path.join(settings.MEDIA_ROOT, g_rel)
                if not (os.path.exists(g_target) and os.path.getsize(g_target) > 5000):
                    generate_clean_image(
                        g_target,
                        p_info['name'],
                        p_info['brand'],
                        p_info['category'],
                        p_info['price'],
                        p_info['mrp'],
                        is_gallery=True,
                        view_num=g_idx
                    )

        with concurrent.futures.ThreadPoolExecutor(max_workers=8) as executor:
            list(executor.map(process_img_task, products_catalog))

        import hashlib
        self.stdout.write("Populating products into database...")
        created_count = 0
        updated_count = 0

        for idx, p_info in enumerate(products_catalog, start=101):
            cat = cat_objs[p_info['category']]
            brand = brand_objs[p_info['brand']]
            img_rel_path = f"products/{p_info['slug']}.jpg"
            unique_sku = f"SHP-{idx:04d}-{hashlib.md5(p_info['slug'].encode()).hexdigest()[:8].upper()}"

            product, created = Product.objects.update_or_create(
                slug=p_info['slug'],
                defaults={
                    'name': p_info['name'],
                    'brand': brand,
                    'category': cat,
                    'mrp': Decimal(str(p_info['mrp'])),
                    'price': Decimal(str(p_info['price'])),
                    'stock': p_info['stock'],
                    'rating': Decimal(str(p_info['rating'])),
                    'review_count': p_info['review_count'],
                    'badge': p_info['badge'],
                    'delivery_days': p_info['delivery_days'],
                    'is_featured': p_info['is_featured'],
                    'is_bestseller': p_info['is_bestseller'],
                    'is_deal': p_info['is_deal'],
                    'warranty': p_info['warranty'],
                    'verified_source': p_info['verified_source'],
                    'price_verified_date': date(2026, 10, 15),
                    'description': p_info['description'],
                    'highlights': p_info['highlights'],
                    'specifications': p_info['specifications'],
                    'image': img_rel_path,
                    'sku': unique_sku,
                }
            )

            if created:
                created_count += 1
            else:
                updated_count += 1

            # Update gallery views
            ProductImage.objects.filter(product=product).delete()
            ProductImage.objects.create(
                product=product,
                image=f"products/gallery/{p_info['slug']}_view1.jpg",
                alt_text=f"{product.name} - Front Angle",
                order=1
            )
            ProductImage.objects.create(
                product=product,
                image=f"products/gallery/{p_info['slug']}_view2.jpg",
                alt_text=f"{product.name} - Studio Perspective",
                order=2
            )

        self.stdout.write(self.style.SUCCESS(
            f"Successfully populated Shopora Catalog: {created_count} created, {updated_count} updated. Total active products in database: {Product.objects.count()}."
        ))
